import csv, io, json, os, sys, unicodedata


def norm_id(s):
    return str(s).strip().lower()


def norm_text(s):
    s = str(s).casefold()
    s = ''.join(c if unicodedata.category(c)[0] in 'LN' else ' ' for c in s)
    return ' '.join(s.split())


def read_batch(path):
    """Return (batch, revision, status, records); record = (contest, [(rank, mark)])
    where mark is ('c', id) or ('w', text)."""
    with open(path, encoding='utf-8', newline='') as f:
        text = f.read()
    records = []
    if path.endswith('.jsonl'):
        head = None
        for line in text.split('\n'):
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            if head is None:
                head = obj
                continue
            marks = []
            for m in obj.get('marks', []):
                r = int(m['rank'])
                if m.get('write_in') is not None:
                    marks.append((r, ('w', m['write_in'])))
                elif m.get('candidate') is not None:
                    marks.append((r, ('c', norm_id(m['candidate']))))
            records.append((obj['contest'], marks))
        head = head or {}
        batch, rev, status = head.get('batch'), head.get('revision'), head.get('status')
    else:
        lines = text.replace('\r\n', '\n').split('\n')
        d = {}
        i = 0
        while i < len(lines) and (lines[i].startswith('#') or not lines[i].strip()):
            l = lines[i]
            if l.startswith('#') and ':' in l:
                k, v = l[1:].split(':', 1)
                d[k.strip().lower()] = v.strip()
            i += 1
        rows = list(csv.reader(io.StringIO('\n'.join(lines[i:]), newline='')))
        rows = [r for r in rows if r]
        batch, rev, status = d.get('batch'), d.get('revision'), d.get('status')
        if rows:
            header = [h.strip() for h in rows[0]]
            ci = {h: j for j, h in enumerate(header)}
            rcols = []
            for h, j in ci.items():
                if h.lower().startswith('rank') and h[4:].isdigit():
                    rcols.append((int(h[4:]), j))
            for row in rows[1:]:
                contest = row[ci['contest']]
                marks = []
                for r, j in rcols:
                    if j >= len(row):
                        continue
                    for part in row[j].split('|'):
                        p = part.strip()
                        if not p:
                            continue
                        if p[:3].upper() == 'WI:':
                            marks.append((r, ('w', p[3:])))
                        else:
                            marks.append((r, ('c', norm_id(p))))
                records.append((contest, marks))
    return str(batch), int(str(rev).strip()), str(status).strip().lower(), records


def read_ballot(marks, max_ranks, writeins, withdrawn):
    """Return list of rankings, each ('skip',) / ('pass',) / ('choice', set)."""
    by_rank = {r: [] for r in range(1, max_ranks + 1)}
    for r, m in marks:
        if r in by_rank:
            by_rank[r].append(m)
    seen = set()
    out = []
    for r in range(1, max_ranks + 1):
        cands = set()
        for kind, v in by_rank[r]:
            if kind == 'c':
                cands.add(v)
            else:
                w = writeins.get(norm_text(v))
                if w is not None:
                    cands.add(w)
        if not cands:
            out.append(('skip', None))
            continue
        cands -= withdrawn
        if not cands:
            out.append(('pass', None))
            continue
        prior = seen
        seen = seen | cands
        cands = cands - prior
        if not cands:
            out.append(('skip', None))
            continue
        out.append(('choice', frozenset(cands)))
    return out


def count_for(rk, continuing):
    n = len(rk)
    i = 0
    while i < n:
        kind, c = rk[i]
        if kind == 'choice':
            if len(c) > 1:
                return None
            (x,) = c
            if x in continuing:
                return x
        elif kind == 'skip':
            if i + 1 < n and rk[i + 1][0] == 'skip':
                return None
        i += 1
    return None


def run_contest(contest, records):
    max_ranks = contest['max_ranks']
    names = {}
    withdrawn = set()
    order = []
    for c in contest['candidates']:
        k = norm_id(c['id'])
        names[k] = c['id']
        if c.get('status') == 'withdrawn':
            withdrawn.add(k)
        else:
            order.append(k)
    writeins = {}
    for w in contest.get('write_ins', []):
        k = norm_id(w['id'])
        names[k] = w['id']
        order.append(k)
        for t in [w['name']] + list(w.get('aliases', [])):
            writeins.setdefault(norm_text(t), k)
    lot = [norm_id(x) for x in contest.get('lot_order', [])]
    ballots = [read_ballot(m, max_ranks, writeins, withdrawn) for m in records]
    total = len(ballots)
    continuing = set(order)
    rounds = []
    history = []
    winner = None
    while True:
        tallies = {c: 0 for c in continuing}
        active = 0
        for rk in ballots:
            x = count_for(rk, continuing)
            if x is not None:
                tallies[x] += 1
                active += 1
        history.append(tallies)
        rd = {'round': len(rounds) + 1,
              'tallies': {names[c]: v for c, v in tallies.items()},
              'exhausted': total - active, 'eliminated': []}
        rounds.append(rd)
        if active == 0:
            break
        top = max(tallies, key=lambda c: tallies[c])
        if tallies[top] * 2 > active or len(continuing) == 1:
            winner = top
            break
        zeros = [c for c in continuing if tallies[c] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tallies.values())
            tied = [c for c in continuing if tallies[c] == m]
            for h in reversed(history[:-1]):
                if len(tied) == 1:
                    break
                mm = min(h[c] for c in tied)
                tied = [c for c in tied if h[c] == mm]
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lot.index(c) if c in lot else -1)]
            elim = tied
        rd['eliminated'] = sorted(names[c] for c in elim)
        continuing -= set(elim)
    return {'contest': contest['id'], 'ballots': total,
            'winner': names[winner] if winner else None, 'rounds': rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        election = json.load(f)
    cvr = os.path.join(inp, 'cvr')
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        b, rev, status, recs = read_batch(p)
        if b not in best or rev > best[b][0]:
            best[b] = (rev, status, recs)
    per = {}
    for rev, status, recs in best.values():
        if status == 'void':
            continue
        for contest, marks in recs:
            per.setdefault(contest, []).append(marks)
    res = {'election': election['election'],
           'contests': [run_contest(c, per.get(c['id'], [])) for c in election['contests']]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False)


main()
